import React,{useEffect,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,ArrowRight,ArrowUpRight,Bell,BookOpen,CalendarDays,Check,CheckCircle2,ChevronDown,ClipboardCheck,Download,Eye,EyeOff,FileText,GraduationCap,HeartPulse,LayoutDashboard,LogOut,Menu,MessageCircle,Plus,Search,Settings,ShieldCheck,Sparkles,Target,Trash2,TrendingUp,Users,WifiOff,X,Pencil,Send,Upload,School,HelpCircle} from 'lucide-react';
import {ResponsiveContainer,BarChart,Bar,XAxis,YAxis,Tooltip,CartesianGrid,LineChart,Line,Legend,RadarChart,PolarGrid,PolarAngleAxis,Radar,PolarRadiusAxis} from 'recharts';
import {api,send,Row,fmt,dateLabel,today,download,readLocal,writeLocal,clearLocal,ApiError} from './api';
import './styles.css';
import {CorrectionForm} from './CorrectionForm';

type Field={key:string;label:string;type:string;required:boolean;options?:string[]};
type Spec={title:string;singular:string;fields:Field[];can_write:boolean;student:boolean;classroom:boolean};
type Catalog=Record<string,Spec>;
const roleNames:Record<string,string>={admin:'Administrador técnico',diretor:'Diretor',coordenador:'Coordenador',professor:'Professor',responsavel:'Responsável',aluno:'Aluno'};
const colors=['#ff5a36','#557bc5','#239b87','#bd8e34','#9473ce','#d46b93','#5a7887'];
function Brand(){return <div className="brand"><img src="/icon.svg" alt=""/><span>Física<span className="brand-light">Mente</span><small>EDUCAÇÃO EM MOVIMENTO</small></span></div>}
function Empty({title='Nada por aqui ainda',text='Os registros aparecerão aqui assim que forem cadastrados.',action}:{title?:string;text?:string;action?:React.ReactNode}){return <div className="empty"><div className="empty-icon"><BookOpen size={28}/></div><h3>{title}</h3><p>{text}</p>{action}</div>}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){
  const ref=React.useRef<HTMLDialogElement>(null);
  useEffect(()=>{ref.current?.showModal();const listener=(e:Event)=>{e.preventDefault();onClose()};const node=ref.current;node?.addEventListener('cancel',listener);return()=>node?.removeEventListener('cancel',listener)},[]);
  return <dialog ref={ref} className="modal"><div className="modal-heading"><h2>{title}</h2><button type="button" className="icon-button" aria-label="Fechar" onClick={onClose}><X/></button></div>{children}</dialog>
}
function Password({name='password',label='Senha',minLength=10,newPassword=false}:{name?:string;label?:string;minLength?:number;newPassword?:boolean}){const[show,setShow]=useState(false);return <label>{label}<div className="password"><input name={name} type={show?'text':'password'} minLength={minLength} maxLength={128} required autoComplete={newPassword||name==='confirm'?'new-password':'current-password'}/><button type="button" aria-label={show?'Ocultar senha':'Mostrar senha'} onClick={()=>setShow(!show)}>{show?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></label>}

function Auth({onLogin}:{onLogin:()=>void}){
 const params=new URLSearchParams(location.search);const action=params.get('action');
 const[mode,setMode]=useState(action==='verify'?'verify':action==='reset'?'reset':action==='invite'?'invite':location.pathname==='/cadastro'?'register':'login');
 const[error,setError]=useState(''),[notice,setNotice]=useState(''),[devLink,setDevLink]=useState(''),[busy,setBusy]=useState(false),[terms,setTerms]=useState(false);
 const[authConfig,setAuthConfig]=useState<{email_verification_required:boolean;email_delivery_available:boolean}|null>(null);
 useEffect(()=>{api('/auth/config').then(setAuthConfig).catch(()=>{})},[]);
 const change=(next:string)=>{setMode(next);setError('');setNotice('');setDevLink('');history.replaceState({},'',next==='register'?'/cadastro':'/')};
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');const data=Object.fromEntries(new FormData(e.currentTarget));try{
  if(['register','invite','reset'].includes(mode)&&data.password!==data.confirm)throw new Error('As senhas não coincidem.');
  let result:any;
  if(mode==='login'){await send('/auth/login',{email:data.email,password:data.password});onLogin();return}
  if(mode==='register')result=await send('/auth/register',{name:data.name,email:data.email,school:data.school,password:data.password,accepted_terms:data.terms==='on'});
  if(mode==='forgot'||mode==='resend')result=await send('/auth/'+mode,{email:data.email});
  if(mode==='verify')result=await send('/auth/verify',{token:params.get('token')});
  if(mode==='reset')result=await send('/auth/reset',{token:params.get('token'),password:data.password});
  if(mode==='invite')result=await send('/auth/accept',{token:params.get('token'),password:data.password,name:data.name});
  if(mode==='register'&&result.can_login){await send('/auth/login',{email:data.email,password:data.password});history.replaceState({},'','/');onLogin();return}
  setNotice(result.message);setDevLink(result.development_link||'');if(['verify','reset','invite'].includes(mode)){setMode('login');history.replaceState({},'',location.pathname)}
 }catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 const heading:Record<string,string>={login:'Bom ter você por aqui.',register:'Uma escola. Muitos caminhos.',forgot:'Vamos recuperar seu acesso.',resend:'Confirme seu e-mail.',verify:'Seu próximo passo começa aqui.',reset:'Escolha uma nova senha.',invite:'Você faz parte desse time.'};
 return <div className="auth-page"><section className="auth-story"><Brand/><div className="story-content"><span className="eyebrow"><span/> CADA MOVIMENTO CONTA</span><h1>O desenvolvimento<br/>tem muitos<br/><em>caminhos.</em></h1><p>Acompanhe cada conquista. Transforme observações em cuidado e movimento em aprendizado.</p><div className="orbit-art" aria-hidden="true"><div className="orbit a"/><div className="orbit b"/><div className="orbit c"/><div className="orbit-core"><Activity size={58}/></div><span className="float-tag tag-one"><TrendingUp size={17}/> Evoluir, juntos.</span><span className="float-tag tag-two"><CheckCircle2 size={17}/> Cada conquista importa</span></div></div><div className="story-footer"><span>FísicaMente</span><span>Mais que avaliar. Acompanhar.</span></div></section><section className="auth-form-side"><div className="auth-top">{mode==='login'?<>Sua escola ainda não está aqui? <button className="text-button" onClick={()=>change('register')}>Criar conta <ArrowUpRight size={15}/></button></>:<>Já tem uma conta? <button className="text-button" onClick={()=>change('login')}>Entrar <ArrowUpRight size={15}/></button></>}</div><div className="auth-form"><span className="eyebrow orange">{mode==='register'?'COMECE SUA JORNADA':'BEM-VINDO AO FÍSICAMENTE'}</span><h2>{heading[mode]}</h2><p className="muted">{mode==='register'?'Crie a conta de gestão e organize o acompanhamento da sua escola.':mode==='login'?'Entre para acompanhar quem está em movimento.':mode==='invite'?'Complete seus dados para aceitar o convite da escola.':'Siga as instruções abaixo para continuar.'}</p><form key={mode} onSubmit={submit}>
 {['register','invite'].includes(mode)&&<label>Nome completo<input name="name" autoComplete="name" placeholder="Como podemos chamar você?" required minLength={2}/></label>}
 {mode==='register'&&<label>Nome da escola<input name="school" placeholder="Ex.: Escola Horizonte" required minLength={2}/></label>}
 {['login','register','forgot','resend'].includes(mode)&&<label>E-mail<input name="email" type="email" autoComplete="email" placeholder="voce@escola.com.br" required/></label>}
 {['login','register','reset','invite'].includes(mode)&&<Password minLength={mode==='login'?1:10} newPassword={mode!=='login'}/>}
 {['register','reset','invite'].includes(mode)&&<><Password name="confirm" label="Confirme a senha"/><small className="muted">Use entre 10 e 128 caracteres.</small></>}
 {mode==='login'&&authConfig?.email_delivery_available!==false&&<div className="auth-links"><button type="button" className="text-button" onClick={()=>change('resend')}>Confirmar e-mail</button><button type="button" className="text-button" onClick={()=>change('forgot')}>Esqueci minha senha</button></div>}
 {mode==='register'&&authConfig?.email_verification_required===false&&<p className="muted" style={{fontSize:11,marginTop:14}}>Seu acesso será liberado após o cadastro, sem aguardar confirmação por e-mail.</p>}
 {mode==='register'&&<label className="checkbox"><input type="checkbox" name="terms" required/><span>Li os <button type="button" className="text-button" onClick={()=>setTerms(true)}>termos e o aviso de privacidade</button>.</span></label>}
 {error&&<div className="error" role="alert">{error}</div>}{notice&&<div className="success" role="status">{notice}</div>}
 {devLink&&<div className="dev-note">Ambiente local, sem servidor de e-mail.<a href={devLink}>Abrir link de confirmação <ArrowUpRight size={14}/></a></div>}
 <button className="btn primary full" disabled={busy}>{busy?'Aguarde…':mode==='login'?'Entrar na minha conta':mode==='register'?'Criar minha conta':mode==='verify'?'Confirmar meu e-mail':mode==='invite'?'Aceitar convite':'Continuar'}<ArrowRight size={18}/></button>
 </form><div className="auth-trust"><ShieldCheck size={18}/><span>Um espaço para cuidar de cada trajetória.</span></div></div><footer className="auth-footer">Educação física com propósito. <span>FísicaMente © {new Date().getFullYear()}</span></footer></section>{terms&&<Modal title="Termos e privacidade · versão inicial" onClose={()=>setTerms(false)}><p>O FísicaMente organiza registros escolares de educação física. A instituição define os usuários autorizados e a finalidade dos registros.</p><p>São tratados dados de identificação, vínculo escolar e avaliações. Informações de saúde e anexos têm acesso restrito. Cada usuário deve manter sua senha privada e registrar apenas informações necessárias ao acompanhamento.</p><p>A escola deve informar aos responsáveis seus canais de atendimento, prazos de retenção e procedimentos para consulta, correção ou exclusão. Autorizações específicas podem ser registradas no módulo Autorizações.</p><p>Este texto é inicial e deve ser adaptado pela instituição antes do uso em produção.</p><button className="btn primary" onClick={()=>setTerms(false)}>Entendi</button></Modal>}</div>
}

const groups=[
 {name:'ACOMPANHAMENTO',items:[['dashboard','Visão geral',LayoutDashboard],['evaluate','Avaliar alunos',ClipboardCheck],['evolution','Evolução',TrendingUp],['alerts','Atenção pedagógica',Bell],['reports','Relatórios',FileText]]},
 {name:'ESCOLA',items:[['alunos','Alunos',GraduationCap],['turmas','Turmas',Users],['responsaveis','Responsáveis',Users],['teachers','Professores',Users],['anos','Anos letivos',CalendarDays],['series','Séries',BookOpen],['modelos','Modelos de avaliação',ClipboardCheck],['ciclos','Ciclos',CalendarDays]]},
 {name:'PRÁTICA PEDAGÓGICA',items:[['aulas','Aulas',BookOpen],['frequencias','Frequência',CheckCircle2],['testes','Testes físicos',Activity],['resultados','Resultados físicos',TrendingUp],['metas','Metas',Target],['planos','Intervenções',Target],['atividades','Atividades',Sparkles],['observacoes','Observações de aula',Eye],['avaliacoes-professores','Avaliar professores',ClipboardCheck],['autoavaliacoes','Autoavaliação',HeartPulse]]},
 {name:'CUIDADO E COMUNIDADE',items:[['saude','Saúde e inclusão',HeartPulse],['afastamentos','Afastamentos',CalendarDays],['consentimentos','Autorizações',ShieldCheck],['attachments','Documentos e atestados',FileText],['comunicados','Comunicados',Bell],['mensagens','Mensagens',MessageCircle],['reunioes','Reuniões',CalendarDays],['eventos','Eventos esportivos',Activity],['inscricoes','Inscrições',Users],['agendamentos','Envios agendados',Send]]},
 {name:'GESTÃO',items:[['users','Usuários e convites',Users],['audit','Histórico de ações',ShieldCheck],['settings','Configurações',Settings]]}
];

function App(){
 const[user,setUser]=useState<any>(null),[initial,setInitial]=useState(true),[catalog,setCatalog]=useState<Catalog>({}),[data,setData]=useState<Record<string,Row[]>>({}),[users,setUsers]=useState<Row[]>([]),[dashboard,setDashboard]=useState<any>({}),[page,setPage]=useState('dashboard'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[toast,setToast]=useState(''),[menu,setMenu]=useState(false),[online,setOnline]=useState(navigator.onLine),[queue,setQueue]=useState<any[]>([]),[search,setSearch]=useState('');
 const notify=(message:string)=>{setToast(message);setTimeout(()=>setToast(''),5000)};
 const[reviewQueue,setReviewQueue]=useState(false),[discardKey,setDiscardKey]=useState<string|null>(null);
 const navigate=(value:string)=>{setPage(value);setSearch('');setMenu(false);setError('')};
 const session=async()=>{try{const u=await api('/me');setUser(u);await writeLocal('session',u)}catch(e){if(e instanceof ApiError){setUser(null);await clearLocal()}else{const cached=await readLocal('session');if(cached){setUser(cached);setOnline(false)}}}finally{setInitial(false)}};
 async function refresh(u=user){if(!u)return;setBusy(true);setError('');try{
   const c:Catalog=await api('/catalog');setCatalog(c);
   const results=await Promise.all(Object.keys(c).map(async key=>[key,await api('/records/'+key)] as const));const d=Object.fromEntries(results);setData(d);
   const [people,board]=await Promise.all([api('/users'),api('/dashboard')]);setUsers(people);setDashboard(board);
   // Only the minimum pedagogical data is cached. Health, messages and documents stay online.
   const safe=Object.fromEntries(Object.entries(d).filter(([k])=>['alunos','turmas','modelos','ciclos'].includes(k)));
   await writeLocal('cache:'+u.id,{catalog:c,data:safe,dashboard:board});setOnline(true);
 }catch(e){if(!(e instanceof ApiError)){const cache=await readLocal('cache:'+u.id);if(cache){setCatalog(cache.catalog);setData(cache.data);setDashboard(cache.dashboard);setOnline(false)}else setError('Sem conexão. Conecte-se para carregar os dados da escola.')}else if(e.status===401){setUser(null);await clearLocal()}else setError(e.message)}finally{setBusy(false)}}
 useEffect(()=>{session();const on=()=>setOnline(true),off=()=>setOnline(false);window.addEventListener('online',on);window.addEventListener('offline',off);return()=>{window.removeEventListener('online',on);window.removeEventListener('offline',off)}},[]);
 useEffect(()=>{if(user){refresh(user);readLocal('queue:'+user.id).then(q=>setQueue(q||[]))}},[user?.id]);
 useEffect(()=>{if(online&&user)refresh(user)},[online]);
 async function enqueue(evaluations:any[]){const next=[...queue,...evaluations];await writeLocal('queue:'+user.id,next);setQueue(next);notify('Avaliações guardadas neste dispositivo. Sincronize quando voltar a conexão.')}
 async function sync(){if(!queue.length)return;setBusy(true);try{await send('/evaluations',{evaluations:queue});await writeLocal('queue:'+user.id,[]);setQueue([]);notify('Avaliações sincronizadas.');await refresh()}catch(e){setError('Não foi possível sincronizar. Os registros continuam guardados: '+(e as Error).message)}finally{setBusy(false)}}
 useEffect(()=>{if(online&&queue.length&&!busy)sync()},[online,queue.length]);
 async function logout(){if(queue.length){setError('Sincronize as avaliações pendentes antes de sair para não perder registros.');return}try{await send('/auth/logout',{});await clearLocal();setUser(null);setData({});navigate('dashboard')}catch{setError('Conecte-se à internet para encerrar a sessão com segurança.')}}
 function visible(key:string){if(catalog[key])return true;if(key==='dashboard')return true;if(['evaluate','alerts'].includes(key))return ['professor','coordenador'].includes(user.role);if(['evolution','reports'].includes(key))return ['professor','coordenador','responsavel','aluno'].includes(user.role);if(key==='teachers')return user.role==='coordenador';if(['users','settings'].includes(key))return ['coordenador','admin'].includes(user.role);if(key==='attachments')return ['coordenador','responsavel'].includes(user.role);if(key==='audit')return ['coordenador','diretor','admin'].includes(user.role);return false}
 if(initial)return <div className="loading-screen"><Brand/><span className="muted">Preparando seu espaço…</span></div>;
 if(!user)return <Auth onLogin={session}/>;
 const title=groups.flatMap(g=>g.items).find(i=>i[0]===page)?.[1] as string||'Visão geral';
 const common={user,data,users,notify,refresh,setError};
 return <div className={'app '+(menu?'menu-open':'')}><aside className="sidebar"><Brand/><div className="school-badge"><span className="school-icon"><School size={19}/></span><div><strong>{user.school.name}</strong><small>Espaço da escola</small></div><ChevronDown size={15}/></div><nav aria-label="Menu principal">{groups.map(group=>{const items=group.items.filter(i=>visible(i[0] as string));return items.length?<div className="nav-group" key={group.name}><span>{group.name}</span>{items.map(([key,label,Icon]:any)=><button key={key} className={page===key?'active':''} onClick={()=>navigate(key)}><Icon size={18}/><span>{label}</span>{key==='alerts'&&dashboard.alerts?.length>0&&<b>{dashboard.alerts.length}</b>}</button>)}</div>:null})}</nav><div className="sidebar-bottom"><div className="avatar">{user.name.slice(0,1)}</div><div><strong>{user.name}</strong><small>{roleNames[user.role]}</small></div><button className="icon-button" onClick={logout} aria-label="Sair"><LogOut size={18}/></button></div></aside><div className="workspace"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="Abrir menu" onClick={()=>setMenu(!menu)}><Menu/></button><span>Meu espaço</span><span>/</span><strong>{title}</strong></div><div className="topbar-actions"><span className={'connection '+(!online?'offline':'')}><span/>{online?'Conectado':'Modo offline'}</span><span className="top-date">{new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long'})}</span><button className="icon-button" aria-label="Notificações e alertas" onClick={()=>navigate(visible('alerts')?'alerts':'comunicados')}><Bell size={19}/></button><div className="avatar small">{user.name.slice(0,1)}</div></div></header><main>
 {error&&<div className="error global-error" role="alert">{error}<button className="icon-button" aria-label="Fechar erro" onClick={()=>setError('')}><X size={16}/></button></div>}
 {queue.length>0&&<div className="queue-banner"><WifiOff size={18}/>{queue.length} avaliação(ões) aguardando envio.<button className="btn small" onClick={()=>setReviewQueue(true)}>Revisar fila</button><button className="btn small primary" disabled={!online||busy} onClick={sync}>Sincronizar agora</button></div>}
 {!online&&<div className="notice">Você pode preparar avaliações com os últimos dados carregados. Os demais módulos precisam de conexão.</div>}
 {page==='dashboard'&&<Dashboard {...common} dashboard={dashboard} navigate={navigate}/>}
 {catalog[page]&&<ModulePage key={page} kind={page} spec={catalog[page]} {...common} search={search} setSearch={setSearch} online={online}/>}
 {page==='evaluate'&&<Evaluate {...common} online={online} enqueue={enqueue}/>}
 {['evolution','reports'].includes(page)&&<Evolution {...common} report={page==='reports'}/>}
 {page==='alerts'&&<Alerts {...common} alerts={dashboard.alerts||[]}/>}
 {page==='users'&&<UsersPage {...common}/>}
 {page==='teachers'&&<Teachers {...common}/>}
 {page==='settings'&&<SettingsPage {...common} onUser={session}/>}
 {page==='audit'&&<AuditPage users={users}/>}
 {page==='attachments'&&<Attachments {...common}/>}
 <footer className="workspace-footer"><span>FísicaMente · Cada movimento conta.</span><span>{busy?'Atualizando dados…':'Seu espaço de acompanhamento escolar'}</span></footer></main></div>{toast&&<div className="toast" role="status"><CheckCircle2 size={20}/>{toast}</div>}{reviewQueue&&<Modal title="Avaliações neste dispositivo" onClose={()=>setReviewQueue(false)}><p>Os registros permanecem aqui até o servidor confirmar o recebimento. Se um vínculo ou ciclo ficou inválido, descarte o lançamento e registre novamente com os dados corretos.</p>{queue.map(q=><div className="attachment" key={q.request_key}><div><strong>{data.alunos?.find(s=>s.id===q.student_id)?.name||'Aluno'}</strong><small>{dateLabel(q.date)} · {Object.entries(q.scores).map(([k,v])=>`${k}: ${v}`).join(', ')}</small></div><button className="btn small" onClick={()=>setDiscardKey(q.request_key)}>Descartar</button></div>)}{discardKey&&<div className="error">Descartar esta avaliação remove a cópia local ainda não confirmada.<div className="form-actions"><button className="btn" onClick={()=>setDiscardKey(null)}>Manter</button><button className="btn danger-fill" onClick={async()=>{const next=queue.filter(q=>q.request_key!==discardKey);await writeLocal('queue:'+user.id,next);setQueue(next);setDiscardKey(null)}}>Confirmar descarte</button></div></div>}</Modal>}</div>
}

type Common={user:any;data:Record<string,Row[]>;users:Row[];notify:(s:string)=>void;refresh:()=>Promise<void>;setError:(s:string)=>void};
function Heading({eyebrow,title,description,children}:{eyebrow?:string;title:string;description:string;children?:React.ReactNode}){return <div className="page-heading"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>}

function Dashboard({user,data,dashboard:d,navigate}:Common&{dashboard:any;navigate:(s:string)=>void}){
 const staff=['coordenador','professor'].includes(user.role),setup=user.role==='coordenador'&&!(data.alunos?.length);
 if(user.role==='admin')return <><Heading title="Gestão de acesso" description="Organize os usuários e acompanhe as ações da plataforma."/><div className="stats"><Stat label="Usuários na escola" value={d.users||0} icon={<Users/>}/></div><button className="btn primary" onClick={()=>navigate('users')}>Gerenciar usuários <ArrowRight size={17}/></button></>;
 const coverage=d.eligible?Math.round(d.evaluated/d.eligible*100):0;
 return <><Heading eyebrow="CADA ALUNO, UMA TRAJETÓRIA" title={`Olá, ${user.name.split(' ')[0]}.`} description={staff?'Um novo dia para acompanhar conquistas e descobrir possibilidades.':'Acompanhe o desenvolvimento e as conquistas ao longo do tempo.'}>{staff&&<button className="btn primary" onClick={()=>navigate('evaluate')}><Plus size={18}/> Nova avaliação</button>}</Heading><section className="welcome-banner"><div><span className="eyebrow">ACOMPANHAMENTO CONTÍNUO</span><h2>Pequenos movimentos.<br/>Grandes descobertas.</h2><p>{d.cycle?`Ciclo atual: ${d.cycle}. Cada registro ajuda a contar essa história.`:'Prepare sua escola para começar a acompanhar cada trajetória.'}</p><button className="text-button" onClick={()=>navigate(setup?'turmas':staff?'evolution':'comunicados')}>{setup?'Organizar minha escola':'Explorar acompanhamento'}<ArrowRight size={17}/></button></div><div className="banner-art" aria-hidden="true"><div className="ring r1"/><div className="ring r2"/><div className="ring r3"/><div className="movement"><Activity size={64}/></div><span className="art-star">✳</span></div></section><div className="stats"><Stat label="Alunos acompanhados" value={d.students||0} icon={<GraduationCap/>} foot="Trajetórias que importam"/><Stat label="Avaliados no ciclo" value={d.evaluated||0} icon={<ClipboardCheck/>} foot={`${coverage}% de cobertura`}/><Stat label="Média de desenvolvimento" value={fmt(d.average)} icon={<TrendingUp/>} foot="Escala de 1 a 5"/><Stat label="Pontos de atenção" value={Array.isArray(d.alerts)?d.alerts.length:d.alerts||0} icon={<HeartPulse/>} foot="Oportunidades para cuidar" accent/></div>
 {setup&&<div className="card setup-card"><div><span className="pill orange">PRIMEIROS PASSOS</span><h2>Sua escola começa aqui.</h2><p>O ano letivo, o modelo de avaliação e três atividades já estão preparados.</p></div><div className="setup-steps">{[['users','1','Convide professores'],['series','2','Cadastre as séries'],['turmas','3','Organize as turmas'],['alunos','4','Adicione os alunos'],['ciclos','5','Abra um ciclo']].map(([key,n,label])=><button key={key} onClick={()=>navigate(key)}><span>{n}</span>{label}<ArrowUpRight size={15}/></button>)}</div></div>}
 <div className="dashboard-grid"><section className="card"><div className="section-title"><div><h2>O movimento das turmas</h2><p>Média da última avaliação de cada aluno</p></div><span className="pill">Visão geral</span></div>{d.classes?.some((c:any)=>c.average!=null)?<div className="chart"><ResponsiveContainer width="100%" height={260}><BarChart data={d.classes} barSize={36}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name" tickLine={false} axisLine={false}/><YAxis domain={[0,5]} tickLine={false} axisLine={false}/><Tooltip/><Bar dataKey="average" name="Média" fill="#ff5a36" radius={[7,7,0,0]}/></BarChart></ResponsiveContainer></div>:<Empty title="Toda trajetória tem um começo" text="Registre as primeiras avaliações para visualizar o desenvolvimento das turmas."/>}</section><section className="card"><div className="section-title"><div><h2>{staff?'Próximos acompanhamentos':'Sobre o acompanhamento'}</h2><p>{staff?'Alunos aguardando avaliação no ciclo':'Evolução com atenção e contexto'}</p></div><span className="icon-soft"><CalendarDays size={20}/></span></div>{staff&&d.pending?.length?<div className="student-list">{d.pending.slice(0,5).map((s:any,i:number)=><button key={s.id} onClick={()=>navigate('evaluate')}><div className={'avatar pastel p'+i}>{s.name.slice(0,1)}</div><div><strong>{s.name}</strong><small>{data.turmas?.find(c=>c.id===s.class_id)?.name||'Aluno'}</small></div><span className="pill">Pendente</span><ArrowUpRight size={16}/></button>)}</div>:<Empty title={staff?'Tudo pronto para acompanhar':'Cada pessoa tem seu ritmo'} text={staff?'As pendências de avaliação aparecerão aqui.':'Os registros ajudam a reconhecer conquistas e planejar os próximos passos.'}/>}</section></div>
 <section className="card"><div className="section-title"><div><h2>Uma visão de cada turma</h2><p>Participação no ciclo e desenvolvimento registrado</p></div></div>{d.classes?.length?<div className="table-wrap"><table><thead><tr><th>Turma</th><th>Alunos</th><th>Avaliados</th><th>Cobertura</th><th>Média</th></tr></thead><tbody>{d.classes.map((c:any)=><tr key={c.id}><td><strong>{c.name}</strong></td><td>{c.students}</td><td>{c.evaluated}</td><td><div className="progress-inline"><div className="progress"><i style={{width:(c.students?c.evaluated/c.students*100:0)+'%'}}/></div><span>{c.students?Math.round(c.evaluated/c.students*100):0}%</span></div></td><td><span className="score">{fmt(c.average)}</span></td></tr>)}</tbody></table></div>:<Empty title="As turmas aparecerão aqui" text="Cadastre turmas para organizar os alunos e acompanhar seus resultados."/>}</section></>
}
function Stat({label,value,icon,foot,accent=false}:{label:string;value:React.ReactNode;icon:React.ReactNode;foot?:string;accent?:boolean}){return <div className={'stat card '+(accent?'accent':'')}><div className="stat-top"><span>{label}</span><div className="icon-soft">{icon}</div></div><strong>{value}</strong><small>{foot}</small></div>}

function ModulePage({kind,spec,data,users,user,notify,refresh,setError,search,setSearch,online}:Common&{kind:string;spec:Spec;search:string;setSearch:(s:string)=>void;online:boolean}){
 const[editing,setEditing]=useState<Row|null|undefined>(),[deleting,setDeleting]=useState<Row|null>(null),[importing,setImporting]=useState(false),[saving,setSaving]=useState(false);
 const rows=(data[kind]||[]).filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));
 const editable=(r:Row)=>spec.can_write&&(!['mensagens','reunioes','consentimentos'].includes(kind)||r.owner_id===user.id);
 async function remove(){if(!deleting)return;setSaving(true);try{await api('/records/'+kind+'/'+deleting.id,{method:'DELETE'});setDeleting(null);notify('Registro removido.');await refresh()}catch(e){setError((e as Error).message);setDeleting(null)}finally{setSaving(false)}}
 const columns=spec.fields.filter(f=>!['textarea','criteria'].includes(f.type)).slice(0,4);
 const display=(r:Row,f:Field)=>{const v=r[f.key];if(f.type.startsWith('ref:'))return (data[f.type.split(':')[1]]||[]).find(x=>x.id===v)?.name||(data[f.type.split(':')[1]]||[]).find(x=>x.id===v)?.year||'—';if(f.type.startsWith('user'))return (Array.isArray(v)?v:[v]).map(id=>users.find(u=>u.id===id)?.name||'Usuário').join(', ');if(f.type.startsWith('date'))return dateLabel(v);return v??'—'};
 return <><Heading eyebrow="ORGANIZAÇÃO E ACOMPANHAMENTO" title={spec.title} description={`${rows.length} registro(s) · Informações da sua escola, sempre conectadas.`}>{kind==='alunos'&&spec.can_write&&<button className="btn" disabled={!online} onClick={()=>setImporting(true)}><Upload size={17}/> Importar CSV</button>}{spec.can_write&&<button className="btn primary" disabled={!online} onClick={()=>setEditing(null)}><Plus size={18}/> Novo registro</button>}</Heading><div className="card"><div className="list-toolbar"><div className="search-field"><Search size={18}/><input aria-label="Buscar registros" value={search} onChange={e=>setSearch(e.target.value)} placeholder={`Buscar em ${spec.title.toLowerCase()}…`}/></div><span className="pill">{rows.length} registros</span></div>{rows.length?<div className="table-wrap"><table><thead><tr>{spec.student&&<th>Aluno</th>}{spec.classroom&&<th>Turma</th>}{columns.map(f=><th key={f.key}>{f.label}</th>)}<th>Detalhes</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}>{spec.student&&<td><strong>{data.alunos?.find(s=>s.id===r.student_id)?.name||'Aluno vinculado'}</strong></td>}{spec.classroom&&<td>{data.turmas?.find(s=>s.id===r.class_id)?.name||'—'}</td>}{columns.map((f,i)=><td key={f.key}>{f.key==='status'?<span className="pill">{display(r,f)}</span>:i===0?<strong>{display(r,f)}</strong>:display(r,f)}</td>)}<td><div className="row-actions"><button className="icon-button" aria-label={editable(r)?'Editar registro':'Ver registro'} onClick={()=>setEditing(r)}>{editable(r)?<Pencil size={16}/>:<Eye size={16}/>}</button>{editable(r)&&<button className="icon-button danger" aria-label="Excluir registro" onClick={()=>setDeleting(r)}><Trash2 size={16}/></button>}</div></td></tr>)}</tbody></table></div>:<Empty title={search?'Nenhum resultado encontrado':`Vamos começar com ${spec.title.toLowerCase()}?`} text={search?'Tente buscar por outro termo.':'Os registros ficam organizados aqui e disponíveis para os perfis autorizados.'} action={spec.can_write&&!search&&<button className="btn primary" onClick={()=>setEditing(null)}><Plus size={17}/> Criar primeiro registro</button>}/>}</div>
 {editing!==undefined&&<RecordForm spec={spec} kind={kind} row={editing} data={data} users={users} readOnly={editing? !editable(editing):false} onClose={()=>setEditing(undefined)} onSaved={async()=>{setEditing(undefined);notify('Registro salvo.');await refresh()}}/>}
 {deleting&&<Modal title="Excluir este registro?" onClose={()=>setDeleting(null)}><p>O registro será arquivado. Se houver vínculos que dependem dele, a exclusão será bloqueada.</p><div className="form-actions"><button className="btn" onClick={()=>setDeleting(null)}>Cancelar</button><button className="btn danger-fill" disabled={saving} onClick={remove}>Excluir registro</button></div></Modal>}
 {importing&&<ImportModal data={data} onClose={()=>setImporting(false)} onSaved={async(n)=>{setImporting(false);notify(`${n} alunos importados.`);await refresh()}}/>}</>
}

function RecordForm({spec,kind,row,data,users,onClose,onSaved,readOnly}:{spec:Spec;kind:string;row:Row|null;data:Record<string,Row[]>;users:Row[];onClose:()=>void;onSaved:()=>Promise<void>;readOnly:boolean}){
 const[values,setValues]=useState<any>(row||{}),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const change=(key:string,value:any)=>setValues((old:any)=>({...old,[key]:value}));
 async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');try{const body={data:Object.fromEntries(spec.fields.map(f=>[f.key,values[f.key]??(f.type==='criteria'?[]:'')])),student_id:spec.student?values.student_id:null,class_id:spec.classroom?values.class_id:null,updated_at:row?.updated_at||null};await send('/records/'+kind+(row?'/'+row.id:''),body,row?'PUT':'POST');await onSaved()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 return <Modal title={`${readOnly?'Detalhes':row?'Editar':'Novo'} · ${spec.singular}`} onClose={onClose}><form onSubmit={submit}><fieldset disabled={readOnly||busy}><div className="form-grid">{spec.student&&<label className="wide">Aluno<select required value={values.student_id||''} onChange={e=>change('student_id',e.target.value)}><option value="">Selecione um aluno</option>{data.alunos?.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label>}{spec.classroom&&<label className="wide">Turma<select required value={values.class_id||''} onChange={e=>change('class_id',e.target.value)}><option value="">Selecione uma turma</option>{data.turmas?.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label>}{spec.fields.map(f=>{
 const value=values[f.key]??'';const options=f.type.startsWith('ref:')?(data[f.type.split(':')[1]]||[]).map(r=>({value:r.id,label:r.name||r.year||r.date})):f.type.startsWith('user')?users.filter(u=>f.type.split(':')[1]==='all'||u.role===f.type.split(':')[1]).map(u=>({value:u.id,label:u.name})):f.options?.map(v=>({value:v,label:v}));
 if(f.type==='criteria')return <div className="wide criteria-editor" key={f.key}><label>Critérios e pesos</label>{(values.criteria||[]).map((c:any,i:number)=><div className="criteria-edit-row" key={i}><input aria-label={'Nome do critério '+(i+1)} value={c.name} required onChange={e=>change('criteria',values.criteria.map((v:any,j:number)=>i===j?{...v,name:e.target.value}:v))}/><input aria-label={'Peso do critério '+(i+1)} type="number" min="0.1" step="0.1" max="100" value={c.weight} required onChange={e=>change('criteria',values.criteria.map((v:any,j:number)=>i===j?{...v,weight:Number(e.target.value)}:v))}/><button className="icon-button" type="button" aria-label="Remover critério" onClick={()=>change('criteria',values.criteria.filter((_:any,j:number)=>j!==i))}><X size={17}/></button></div>)}<button type="button" className="btn small" onClick={()=>change('criteria',[...(values.criteria||[]),{name:'',weight:1}])}><Plus size={15}/> Adicionar critério</button></div>;
 return <label key={f.key} className={f.type==='textarea'||f.type.startsWith('users:')?'wide':''}>{f.label}{f.required&&<span className="required"> *</span>}{f.type==='textarea'?<textarea value={value} required={f.required} onChange={e=>change(f.key,e.target.value)}/>:options?<select multiple={f.type.startsWith('users:')} value={f.type.startsWith('users:')?(value||[]):value} required={f.required} onChange={e=>change(f.key,f.type.startsWith('users:')?Array.from(e.target.selectedOptions,o=>o.value):e.target.value)}>{!f.type.startsWith('users:')&&<option value="">Selecione</option>}{options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:<input type={f.type} value={value} step={f.type==='number'?'any':undefined} required={f.required} onChange={e=>change(f.key,e.target.value)}/>}</label>
 })}</div></fieldset>{error&&<div className="error" role="alert">{error}</div>}<div className="form-actions"><button className="btn" type="button" onClick={onClose}>{readOnly?'Fechar':'Cancelar'}</button>{!readOnly&&<button className="btn primary" disabled={busy}>{busy?'Salvando…':'Salvar registro'}<Check size={17}/></button>}</div></form></Modal>
}

function ImportModal({data,onClose,onSaved}:{data:Record<string,Row[]>;onClose:()=>void;onSaved:(n:number)=>Promise<void>}){const[error,setError]=useState(''),[busy,setBusy]=useState(false);return <Modal title="Importar alunos" onClose={onClose}><p>Use CSV UTF-8, separado por ponto e vírgula. Todos os registros serão validados antes de salvar.</p><pre className="sample">nome;matricula;nascimento;sexo<br/>Ana Silva;2026001;2014-05-20;Feminino</pre><form onSubmit={async e=>{e.preventDefault();setBusy(true);try{const fd=new FormData(e.currentTarget),id=fd.get('class_id');fd.delete('class_id');const r=await api('/import/students?class_id='+id,{method:'POST',body:fd});await onSaved(r.count)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><label>Turma<select name="class_id" required><option value="">Selecione</option>{data.turmas?.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Arquivo CSV<input name="file" type="file" accept=".csv" required/></label>{error&&<div className="error">{error}</div>}<div className="form-actions"><button className="btn primary" disabled={busy}>Validar e importar</button></div></form></Modal>}

function Evaluate({data,notify,refresh,online,enqueue}:Common&{online:boolean;enqueue:(v:any[])=>Promise<void>}){
 const[mode,setMode]=useState('individual'),[classId,setClassId]=useState(''),[studentId,setStudentId]=useState(''),[cycleId,setCycleId]=useState(''),[day,setDay]=useState(today()),[scores,setScores]=useState<Record<string,Record<string,number>>>({}),[strengths,setStrengths]=useState(''),[develop,setDevelop]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);
 const cycle=data.ciclos?.find(c=>c.id===cycleId),model=data.modelos?.find(m=>m.id===cycle?.model_id),criteria=model?.criteria||[];
 const students=(data.alunos||[]).filter(s=>s.status==='Ativo'&&(!classId||s.class_id===classId));
 const targets=mode==='individual'?students.filter(s=>s.id===studentId):classId?students:[];
 const score=(id:string,k:string)=>scores[id]?.[k]??3;
 const setScore=(id:string,k:string,n:number)=>setScores(prev=>({...prev,[id]:{...prev[id],[k]:n}}));
 async function submit(e:React.FormEvent){
  e.preventDefault();setError('');if(!cycleId||!targets.length){setError('Selecione o ciclo e pelo menos um aluno.');return}
  setBusy(true);
  const evaluations=targets.map(s=>({student_id:s.id,cycle_id:cycleId,date:day,scores:Object.fromEntries(criteria.map((c:any)=>[c.name,score(s.id,c.name)])),strengths:mode==='individual'?strengths:'',develop:mode==='individual'?develop:'',request_key:crypto.randomUUID()}));
  try{
   if(!online)await enqueue(evaluations);
   else try{await send('/evaluations',{evaluations});notify(`${targets.length} avaliação(ões) registrada(s).`);await refresh()}catch(e){if(e instanceof TypeError)await enqueue(evaluations);else throw e}
   setStudentId('');setScores({});setStrengths('');setDevelop('');
  }catch(e){setError((e as Error).message)}finally{setBusy(false)}
 }
 return <><Heading eyebrow="OLHAR, REGISTRAR, ACOMPANHAR" title="Cada movimento merece um olhar." description="Avalie com atenção ao percurso de cada aluno. Notas de 1 a 5, em passos de meio ponto."/><div className="segments"><button className={mode==='individual'?'selected':''} onClick={()=>setMode('individual')}>Um aluno</button><button className={mode==='turma'?'selected':''} onClick={()=>setMode('turma')}>Turma inteira</button></div><form onSubmit={submit}><section className="card"><div className="form-grid three"><label>Ciclo de avaliação<select required value={cycleId} onChange={e=>{setCycleId(e.target.value);setScores({})}}><option value="">Selecione o ciclo</option>{data.ciclos?.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Turma<select value={classId} required={mode==='turma'} onChange={e=>{setClassId(e.target.value);setStudentId('')}}><option value="">{mode==='turma'?'Selecione a turma':'Todas as minhas turmas'}</option>{data.turmas?.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Data<input type="date" required max={today()} value={day} onChange={e=>setDay(e.target.value)}/></label>{mode==='individual'&&<label className="wide">Aluno<select required value={studentId} onChange={e=>setStudentId(e.target.value)}><option value="">Selecione quem vamos acompanhar</option>{students.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label>}</div></section>{criteria.length&&targets.length?<section className="card evaluation-card"><div className="section-title"><div><h2>{mode==='individual'?targets[0].name:'Avaliação da turma'}</h2><p>{model?.name} · Os valores iniciais são 3. Revise todos antes de salvar.</p></div><span className="pill">{criteria.length} critérios</span></div>{mode==='individual'?<><div className="sliders">{criteria.map((c:any,i:number)=><div className="slider-row" key={c.name}><label htmlFor={'score-'+i}><span style={{background:colors[i%colors.length]}}/>{c.name}<small>Peso {c.weight}</small></label><div className="slider-control"><span>1</span><input id={'score-'+i} type="range" min="1" max="5" step="0.5" value={score(studentId,c.name)} onChange={e=>setScore(studentId,c.name,Number(e.target.value))}/><span>5</span><output>{fmt(score(studentId,c.name))}</output></div></div>)}</div><div className="form-grid"><label>Pontos fortes<textarea value={strengths} onChange={e=>setStrengths(e.target.value)} placeholder="Quais conquistas você observou?"/></label><label>Pontos a desenvolver<textarea value={develop} onChange={e=>setDevelop(e.target.value)} placeholder="Quais serão os próximos passos?"/></label></div></>:<div className="table-wrap"><table className="evaluation-table"><thead><tr><th>Aluno</th>{criteria.map((c:any)=><th key={c.name}>{c.name}</th>)}</tr></thead><tbody>{targets.map(s=><tr key={s.id}><td>{s.name}</td>{criteria.map((c:any)=><td key={c.name}><input aria-label={`${c.name} de ${s.name}`} type="number" min="1" max="5" step="0.5" required value={score(s.id,c.name)} onChange={e=>setScore(s.id,c.name,Number(e.target.value))}/></td>)}</tr>)}</tbody></table></div>}<div className="form-actions"><span className="muted">{targets.length} avaliação(ões) para registrar</span><button className="btn primary" disabled={busy}><Check size={18}/>{busy?'Salvando…':online?'Salvar avaliação':'Guardar offline'}</button></div></section>:<section className="card"><Empty title="Quem vamos acompanhar hoje?" text="Selecione um ciclo e um aluno ou turma para começar a avaliação."/></section>}{error&&<div className="error">{error}</div>}</form></>
}

function Evolution({data,report,setError,user,notify}:Common&{report:boolean}){
 const[id,setId]=useState(''),[result,setResult]=useState<any>(null),[loading,setLoading]=useState(false),[correcting,setCorrecting]=useState<Row|null>(null);
 useEffect(()=>{let active=true;setResult(null);if(id){setLoading(true);api('/evolution/'+id).then(r=>{if(active)setResult(r)}).catch(e=>setError(e.message)).finally(()=>{if(active)setLoading(false)})}return()=>{active=false}},[id]);
 const history=result?.history||[],criteria=history.length?Object.keys(history[history.length-1].scores):[],chart=history.map((e:any)=>({date:dateLabel(e.date),...e.scores}));
 const getFile=async(path:string,name:string)=>{try{await download(path,name)}catch(e){setError((e as Error).message)}};
 return <><Heading eyebrow="O PERCURSO IMPORTA" title={report?'Histórias que merecem ser compartilhadas.':'Desenvolvimento, ao longo do tempo.'} description={report?'Gere fichas individuais com o histórico e as observações registradas.':'Um olhar para cada critério, cada conquista e cada próximo passo.'}>{id&&<button className="btn primary" onClick={()=>getFile('/reports/'+id+'/pdf','ficha-fisicamente.pdf')}><Download size={17}/> Baixar ficha PDF</button>}</Heading><div className="card filter-card"><label>Aluno<select value={id} onChange={e=>setId(e.target.value)}><option value="">Selecione um aluno</option>{data.alunos?.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label></div>{loading?<div className="card"><Empty title="Carregando percurso…" text="Buscando os registros do aluno."/></div>:!result?<div className="card"><Empty title="Toda história merece atenção" text="Selecione um aluno para conhecer seu percurso."/></div>:<><div className="summary-banner"><Sparkles size={24}/><div><h3>{result.student.name}</h3><p>{result.summary}</p></div></div><div className="stats three"><Stat label="Avaliações registradas" value={history.length} icon={<ClipboardCheck/>}/><Stat label="Variação no percurso" value={fmt(result.delta)} icon={<TrendingUp/>}/><Stat label={result.percentile!=null?'Percentil na turma e ciclo':'Última média'} value={result.percentile!=null?result.percentile+'%':fmt(history.at(-1)?.score)} icon={<Activity/>}/></div>{history.length?<><div className="card"><div className="section-title"><div><h2>Uma trajetória em movimento</h2><p>Notas por critério em cada avaliação</p></div></div><ResponsiveContainer width="100%" height={320}><LineChart data={chart}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="date"/><YAxis domain={[1,5]}/><Tooltip/><Legend/>{criteria.map((c,i)=><Line key={c} dataKey={c} stroke={colors[i%colors.length]} strokeWidth={2} connectNulls={false}/>)}</LineChart></ResponsiveContainer></div><div className="dashboard-grid"><div className="card"><h2>Um olhar para os critérios</h2><ResponsiveContainer width="100%" height={300}><RadarChart data={result.comparison}><PolarGrid/><PolarAngleAxis dataKey="criterion" tick={{fontSize:11}}/><PolarRadiusAxis domain={[0,5]}/><Radar name="Aluno" dataKey="student" stroke="#ff5a36" fill="#ff5a36" fillOpacity={.22}/><Radar name="Média da turma" dataKey="group" stroke="#557bc5" fill="#557bc5" fillOpacity={.08}/><Tooltip/><Legend/></RadarChart></ResponsiveContainer></div><div className="card"><h2>Últimas observações</h2><div className="observation"><span className="pill green">Pontos fortes</span><p>{history.at(-1).strengths||'Nenhuma observação registrada.'}</p></div><div className="observation"><span className="pill orange">Próximos passos</span><p>{history.at(-1).develop||'Nenhuma observação registrada.'}</p></div></div></div><div className="card"><h2>Histórico de avaliações</h2><div className="table-wrap"><table><thead><tr><th>Data</th>{criteria.map(c=><th key={c}>{c}</th>)}<th>Média</th>{['coordenador','professor'].includes(user.role)&&<th>Correção</th>}</tr></thead><tbody>{history.map((e:any)=><tr key={e.id}><td>{dateLabel(e.date)}</td>{criteria.map((c,i)=><td key={c}><span className="heat-cell" style={{background:colors[i%colors.length]+'20'}}>{fmt(e.scores[c])}</span></td>)}<td><strong>{fmt(e.score)}</strong></td>{['coordenador','professor'].includes(user.role)&&<td>{(user.role==='coordenador'||e.owner_id===user.id)&&<button className="btn small" onClick={()=>setCorrecting(e)}>Corrigir</button>}</td>}</tr>)}</tbody></table></div></div></>:<div className="card"><Empty title="O primeiro capítulo está por vir" text="As avaliações deste aluno aparecerão aqui após o primeiro registro."/></div>}</>}{correcting&&<CorrectionForm row={correcting} onClose={()=>setCorrecting(null)} onSaved={async()=>{setCorrecting(null);setResult(await api('/evolution/'+id));notify('Avaliação corrigida. A versão anterior foi preservada.')}}/>}</>
}

function Alerts({alerts,notify,refresh,setError}:Common&{alerts:any[]}){return <><Heading eyebrow="CUIDADO QUE VIRA AÇÃO" title="Atenção pedagógica" description="Sinais para observar com contexto e planejar os próximos passos."/>{alerts.length?<div className="cards-grid">{alerts.map(a=><article className="card" key={a.key}><div className="section-title"><span className="pill orange">{a.type}</span><HeartPulse size={22}/></div><h2>{a.name}</h2><p>{a.criterion}: {fmt(a.from_value)} → {fmt(a.to_value)}</p><p className="muted">Converse com o aluno, considere o contexto e registre um plano de acompanhamento quando necessário.</p><button className="btn" onClick={async()=>{try{await send('/alerts/resolve',{key:a.key});notify('Alerta marcado como acompanhado.');await refresh()}catch(e){setError((e as Error).message)}}}><Check size={16}/> Marcar como acompanhado</button></article>)}</div>:<div className="card"><Empty title="Nenhum alerta em aberto" text="Quedas de um ponto e estagnações abaixo da média aparecerão aqui."/></div>}</>}

function UsersPage({users,data,notify,refresh,setError}:Common){const[invite,setInvite]=useState(false),[link,setLink]=useState(''),[error,setLocalError]=useState(''),[role,setRole]=useState('professor'),[busy,setBusy]=useState(false);return <><Heading title="Pessoas que fazem parte" description="Convide a equipe e conecte famílias e alunos à escola."><button className="btn primary" onClick={()=>{setInvite(true);setLink('');setLocalError('')}}><Plus size={18}/> Convidar pessoa</button></Heading><div className="card"><div className="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Situação</th><th>Acesso</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td><strong>{u.name}</strong></td><td>{u.email}</td><td>{roleNames[u.role]}</td><td><span className={'pill '+(u.active?'green':'')}>{u.active?'Ativo':'Inativo'}</span></td><td><button className="btn small" onClick={async()=>{try{await send('/users/'+u.id,{active:!u.active},'PATCH');notify('Acesso atualizado.');await refresh()}catch(e){setError((e as Error).message)}}}>{u.active?'Desativar':'Ativar'}</button></td></tr>)}</tbody></table></div></div>{invite&&<Modal title="Convidar para a escola" onClose={()=>setInvite(false)}><form onSubmit={async e=>{e.preventDefault();setBusy(true);setLocalError('');try{const d=new FormData(e.currentTarget);const r=await send('/invites',{email:d.get('email'),role,student_ids:d.getAll('student_ids')});setLink(r.invite_link||r.development_link||'');notify(r.message);if(!r.invite_link&&!r.development_link)setInvite(false)}catch(e){setLocalError((e as Error).message)}finally{setBusy(false)}}}><label>E-mail<input name="email" type="email" required/></label><label>Perfil<select value={role} onChange={e=>setRole(e.target.value)}>{Object.entries(roleNames).map(([k,v])=><option value={k} key={k}>{v}</option>)}</select></label>{['responsavel','aluno'].includes(role)&&<label>Aluno(s) vinculado(s)<select required multiple={role==='responsavel'} name="student_ids">{data.alunos?.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><small>O acesso será limitado aos alunos selecionados.</small></label>}{error&&<div className="error">{error}</div>}{link&&<div className="dev-note">Compartilhe este convite somente com a pessoa indicada.<a href={link} target="_blank" rel="noreferrer">Abrir convite <ArrowUpRight size={16}/></a><button type="button" className="btn small" onClick={()=>navigator.clipboard.writeText(link).then(()=>notify('Link copiado.')).catch(()=>setLocalError('Não foi possível copiar. Abra o link acima.'))}>Copiar link</button></div>}<div className="form-actions"><button className="btn primary" disabled={busy}><Send size={17}/> Enviar convite</button></div></form></Modal>}</>}

function Teachers({users,data,setError}:Common){const[evaluations,setEvaluations]=useState<Row[]>([]);useEffect(()=>{api('/evaluations').then(setEvaluations).catch(e=>setError(e.message))},[]);return <><Heading title="Quem acompanha cada movimento" description="Indicadores dos professores como apoio à conversa, considerando o contexto das turmas."/><div className="cards-grid">{users.filter(u=>u.role==='professor').map(u=>{const classes=(data.turmas||[]).filter(c=>c.teacher_ids.includes(u.id)),students=(data.alunos||[]).filter(s=>classes.some(c=>c.id===s.class_id)),ev=evaluations.filter(e=>students.some(s=>s.id===e.student_id)),latest:Row[]=Object.values(Object.fromEntries([...ev].sort((a,b)=>a.date.localeCompare(b.date)).map(e=>[e.student_id,e])));return <article className="card" key={u.id}><div className="teacher-heading"><div className="avatar pastel">{u.name.slice(0,1)}</div><div><h2>{u.name}</h2><p className="muted">{classes.map(c=>c.name).join(' · ')||'Sem turmas vinculadas'}</p></div></div><div className="teacher-stats"><div><strong>{students.length}</strong><small>alunos</small></div><div><strong>{latest.length}</strong><small>com avaliações</small></div><div><strong>{latest.length?fmt(latest.reduce((sum,e)=>sum+e.score,0)/latest.length):'—'}</strong><small>média atual</small></div></div></article>})}</div>{!users.some(u=>u.role==='professor')&&<div className="card"><Empty title="Seu time começa com um convite" text="Convide professores em Usuários e convites. Depois, vincule-os às turmas."/></div>}</>}

function SettingsPage({user,notify,setError,onUser}:Common&{onUser:()=>Promise<void>}){const[mails,setMails]=useState<any[]>([]);return <><Heading title="Do jeito da sua escola" description="Configure sua instituição e os serviços de comunicação."/><div className="card narrow"><h2>Identidade da escola</h2><form onSubmit={async e=>{e.preventDefault();try{await send('/settings',{name:new FormData(e.currentTarget).get('name')},'PUT');await onUser();notify('Nome da escola atualizado.')}catch(e){setError((e as Error).message)}}}><label>Nome da instituição<input name="name" defaultValue={user.school.name} required minLength={2}/></label><div className="form-actions"><button className="btn primary">Salvar alterações</button></div></form></div>{user.development&&<div className="card"><span className="pill orange">AMBIENTE LOCAL</span><h2>Caixa de saída de desenvolvimento</h2><p>Os e-mails ficam registrados aqui enquanto o SMTP não está configurado. Os links são privados e expiram.</p><button className="btn" onClick={()=>api('/development-mails').then(setMails).catch(e=>setError(e.message))}>Consultar caixa de saída</button>{mails.map(m=><div className="mail-row" key={m.id}><strong>{m.subject}</strong><small>{m.recipient}</small><p className="break-word">{m.body}</p></div>)}</div>}<div className="card"><h2>Exportar avaliações</h2><p>Baixe um CSV com os registros permitidos para seu perfil.</p><button className="btn" onClick={()=>download('/export/csv','fisicamente.csv').catch(e=>setError(e.message))}><Download size={17}/> Baixar CSV</button></div></>}
function AuditPage({users}:{users:Row[]}){const[rows,setRows]=useState<Row[]>([]),[error,setError]=useState('');useEffect(()=>{api('/audit').then(setRows).catch(e=>setError(e.message))},[]);return <><Heading title="Histórico de ações" description="Últimas 500 ações registradas. Dados sensíveis não aparecem no histórico."/>{error&&<div className="error">{error}</div>}<div className="card table-wrap"><table><thead><tr><th>Quando</th><th>Quem</th><th>Ação</th><th>Registro</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{new Date(r.at).toLocaleString('pt-BR')}</td><td>{users.find(u=>u.id===r.user_id)?.name||'Usuário'}</td><td>{r.action}</td><td className="mono">{r.target}</td></tr>)}</tbody></table></div></>}
function Attachments({user,data,setError,notify}:Common){const[id,setId]=useState(''),[rows,setRows]=useState<Row[]>([]),[busy,setBusy]=useState(false);const load=()=>id?api('/attachments/'+id).then(setRows).catch(e=>setError(e.message)):Promise.resolve();useEffect(()=>{setRows([]);load()},[id]);return <><Heading title="Documentos e atestados" description="Anexos privados, disponíveis à coordenação e aos responsáveis vinculados."/><div className="card"><label>Aluno<select value={id} onChange={e=>setId(e.target.value)}><option value="">Selecione</option>{data.alunos?.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label>{id&&user.role==='coordenador'&&<form className="upload-form" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await api('/attachments/'+id,{method:'POST',body:new FormData(e.currentTarget)});notify('Documento anexado.');await load()}catch(e){setError((e as Error).message)}finally{setBusy(false)}}}><label>Documento (PDF, PNG ou JPEG, até 5 MB)<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" required/></label><button className="btn primary" disabled={busy}><Upload size={16}/> Enviar documento</button></form>}{rows.map(r=><div className="attachment" key={r.id}><FileText/><div><strong>{r.name}</strong><small>{Math.ceil(r.size/1024)} KB</small></div><button className="btn" onClick={()=>download('/attachment/'+r.id+'/download',r.name).catch(e=>setError(e.message))}><Download size={16}/> Baixar</button></div>)}</div></>}

createRoot(document.getElementById('root')!).render(<App/>);
if('serviceWorker' in navigator&&import.meta.env.PROD)navigator.serviceWorker.register('/sw.js');





